CREATE TABLE IF NOT EXISTS conductor_score_runs_v1 (run_id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES zones_registry(project_id),score_id TEXT NOT NULL DEFAULT 'stille-nacht-6-8-72',measure INTEGER NOT NULL DEFAULT 1 CHECK(measure BETWEEN 1 AND 72),stanza INTEGER NOT NULL DEFAULT 1 CHECK(stanza BETWEEN 1 AND 6),beat INTEGER NOT NULL DEFAULT 1 CHECK(beat IN (1,2)),subdivision INTEGER NOT NULL DEFAULT 1 CHECK(subdivision BETWEEN 1 AND 3),state TEXT NOT NULL DEFAULT 'paused' CHECK(state IN ('paused','ready','running','waiting','failed','completed')),approval_required INTEGER NOT NULL DEFAULT 1,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_conductor_score_project ON conductor_score_runs_v1(project_id,state);
CREATE TABLE IF NOT EXISTS conductor_score_receipts_v1 (run_id TEXT NOT NULL,measure INTEGER NOT NULL CHECK(measure BETWEEN 1 AND 72),stage TEXT NOT NULL,receipt_json TEXT NOT NULL,verified INTEGER NOT NULL DEFAULT 0 CHECK(verified IN (0,1)),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(run_id,measure));
